```xUnit Test Cases
namespace U17_GUI
{
    [Test]
    public void DisplayPatientPressure_ShouldDisplayCorrectValue()
    {
        // Arrange
        var controller = new Controller();
        var view = new View(controller);

        // Act
        controller.SetPressure(50); // Example pressure value
        view.UpdateDisplay();

        // Assert
        Assert.Equal(50, view.GetPressureDisplay());
    }

    [Test]
    public void GraphRefreshRate_ShouldBeAtLeast20Hz()
    {
        // Arrange
        var view = new View();
        var timer = new Timer();
        view.SetTimer(timer);

        // Act
        timer.Start();
        view.UpdateDisplay();

        // Assert
        Assert.True(timer.ElapsedMilliseconds >= 50); // 20ms is 20Hz
    }

    [Test]
    public void GraphDuration_ShouldBe30Seconds()
    {
        // Arrange
        var view = new View();
        var timer = new Timer();
        view.SetTimer(timer);

        // Act
        timer.Start();
        view.UpdateDisplay();

        // Assert
        Assert.Equal(30000, timer.ElapsedMilliseconds); // 30 seconds
    }

    [Test]
    public void DisplayInspiratoryTidalVolume_ShouldDisplayCorrectRangeAndResolution()
    {
        // Arrange
        var view = new View();
        var pressure = 500; // Example pressure value
        view.SetPressure(pressure);
        view.UpdateDisplay();

        // Assert
        Assert.True(view.GetTidalVolumeDisplay() >= 0 && view.GetTidalVolumeDisplay() <= 1000);
        Assert.Equal(1, view.GetTidalVolumeDisplay());
    }

    [Test]
    public void DisplayInspirationExpirationRatio_ShouldDisplayCorrectRangeAndResolution()
    {
        // Arrange
        var view = new View();
        var pressure = 500; // Example pressure value
        view.SetPressure(pressure);
        view.UpdateDisplay();

        // Assert
        Assert.True(view.GetExpirationRatioDisplay() >= 10 && view.GetExpirationRatioDisplay() <= 200);
        Assert.Equal(0.1, view.GetExpirationRatioDisplay());
    }

    [Test]
    public void DisplayPEEP_ShouldDisplayCorrectIncrement()
    {
        // Arrange
        var view = new View();
        var pressure = 5; // Example pressure value
        view.SetPressure(pressure);
        view.UpdateDisplay();

        // Assert
        Assert.Equal(5, view.GetPEEPDisplay());
    }

    [Test]
    public void DisplayVolumeGraph_ShouldDisplayCorrectGraph()
    {
        // Arrange
        var view = new View();
        var pressure = 5; // Example pressure value
        view.SetPressure(pressure);
        view.UpdateDisplay();

        // Assert
        Assert.True(view.GetVolumeGraphDisplay().Count() > 0); // Graph must have at least one point
    }

    [Test]
    public void FlowRateGraph_ShouldBeAtLeast20HzAndDisplayCorrectUnits()
    {
        // Arrange
        var view = new View();
        var timer = new Timer();
        view.SetTimer(timer);
        view.SetFlowRate(5); // Example flow rate value
        timer.Start();
        view.UpdateDisplay();

        // Assert
        Assert.True(timer.ElapsedMilliseconds >= 50); // 20ms is 20Hz
        Assert.Equal(5, view.GetFlowRateDisplay()); // 5 L/min
    }
}
